  void CheckGamePreferences() {
   var saved=preferences;preferences=new VeilPreferences();preferences.Normalise();
   Require(DisplayMode(0)==FullScreenMode.ExclusiveFullScreen&&DisplayMode(1)==FullScreenMode.FullScreenWindow&&DisplayMode(2)==FullScreenMode.Windowed,"Display choices map to all three real Unity window modes");
   Require(preferences.Rebind(false,(int)ControlAction.Virtue,(int)Key.C)&&preferences.keys[(int)ControlAction.Character]==(int)Key.Q,"Duplicate key rebinding swaps the previous binding");preferences.master=.4f;preferences.effects=.25f;preferences.menu=.6f;ApplyAudioPreferences();Require(Mathf.Abs(AudioListener.volume-(smoke?0:.4f))<.001f,"Master preference is stored while automated tests remain silent");var restored=JsonUtility.FromJson<VeilPreferences>(JsonUtility.ToJson(preferences));restored.Normalise();Require(restored.master==.4f&&restored.effects==.25f&&restored.menu==.6f&&restored.keys[(int)ControlAction.Virtue]==(int)Key.C,"Volumes and remapped controls survive the settings save format");
   preferences=new VeilPreferences();preferences.Normalise();var keyboard=InputSystem.AddDevice<Keyboard>();var mouse=InputSystem.AddDevice<Mouse>();var pad=InputSystem.AddDevice<Gamepad>();var other=InputSystem.AddDevice<Gamepad>();
   preferences.controller=Gamepad.all.Count-2;Require(PreferredPad==pad,"Explicit controller selection uses the chosen device");preferences.controller=-1;other.MakeCurrent();Require(PreferredPad==other,"Automatic controller mode follows the current device");pad.MakeCurrent();
   StartRun();combatReviewFreeze=true;preferences.Rebind(false,(int)ControlAction.Virtue,(int)Key.R);rage=100;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.Q));InputSystem.Update();ReadRageInput();Require(!RageActive,"The old virtue key stops activating after a remap");InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.R));InputSystem.Update();ReadRageInput();Require(RageActive,"The rebound keyboard key reaches actual Rage activation");
   InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();ResetRage();rage=100;preferences.Rebind(true,(int)ControlAction.Virtue,(int)GamepadButton.North);InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.North));InputSystem.Update();ReadRageInput();Require(RageActive,"A rebound controller button reaches actual Rage activation");
   preferences.inputMode=1;InputSystem.QueueStateEvent(pad,new GamepadState{leftStick=Vector2.right});InputSystem.Update();ReadCombatControls();Require(!gamepadCombat&&movement==Vector2.zero,"Keyboard preference ignores controller gameplay input");preferences.inputMode=2;InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));InputSystem.Update();ReadCombatControls();Require(gamepadCombat&&movement==Vector2.zero,"Controller preference ignores keyboard movement");
   preferences=new VeilPreferences();preferences.Normalise();InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();ReturnHome();
   InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.North));InputSystem.Update();Require(ReadResourceController()&&resourceFocus&&resourceCategory==-1,"Y focuses the resource bar directly");
   InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.RightShoulder));InputSystem.Update();ReadResourceController();Require(resourceFocusCategory==1,"RB moves directly to the ore category");InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.South));InputSystem.Update();ReadResourceController();Require(resourceCategory==1,"A opens the focused resource dropdown");InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.DpadDown));InputSystem.Update();ReadResourceController();Require(resourceFocusRow==1,"D-pad moves the highlighted material row");InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.East));InputSystem.Update();ReadResourceController();Require(!resourceFocus&&resourceCategory==-1,"B releases resource focus without acting on the page beneath");
   OpenSettings();float time=elapsed,charge=rage;Require(state==ScreenState.Settings&&!SimulationActive&&elapsed==time&&rage==charge,"Settings pause both clocks and active resource timers");BeginBinding((int)ControlAction.Dodge,false);captureFrame=Time.frameCount-1;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.Z));InputSystem.Update();CaptureBinding();Require(captureAction==-1&&preferences.keys[(int)ControlAction.Dodge]==(int)Key.Z,"Interactive key capture stores a new binding");CloseSettings();Require(state==ScreenState.Settlement,"Settings return to the originating interface");
   InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);InputSystem.RemoveDevice(pad);InputSystem.RemoveDevice(other);preferences=saved;preferences.Normalise();ApplyAudioPreferences();LeaveResourceBar();Debug.Log("VEILBOUND_SETTINGS_AND_RESOURCE_CONTROLS_PASS");
  }
  IEnumerator GameSettingsReview(string folder) {
   Directory.CreateDirectory(folder);ReturnHome();CheckGamePreferences();var oldPrefs=preferences;var oldMode=Screen.fullScreenMode;int oldW=Screen.width,oldH=Screen.height;
   preferences=new VeilPreferences();preferences.Normalise();OpenSettings();combatReviewFreeze=true;yield return CardScreenshot(Path.Combine(folder,"01-display-settings.png"));settingsTab=1;preferences.master=.8f;preferences.effects=.65f;preferences.menu=.5f;ApplyAudioPreferences();yield return CardScreenshot(Path.Combine(folder,"02-sound-settings.png"));settingsTab=2;yield return CardScreenshot(Path.Combine(folder,"03-controls-and-bindings.png"));BeginBinding((int)ControlAction.Virtue,false);yield return CardScreenshot(Path.Combine(folder,"04-remap-prompt.png"));captureAction=-1;CloseSettings();
