   // Exercise each window-mode request in the real player, then restore the capture window.
   for(int mode=0;mode<3;mode++){preferences.displayMode=mode;preferences.width=oldW;preferences.height=oldH;ApplyDisplayPreferences();yield return new WaitForSecondsRealtime(.45f);Debug.Log("VEILBOUND_DISPLAY_MODE_REQUEST "+DisplayNames[mode]+" actual="+Screen.fullScreenMode+" "+Screen.width+"x"+Screen.height);}
   Screen.SetResolution(oldW,oldH,oldMode);yield return new WaitForSecondsRealtime(.3f);preferences=oldPrefs;ApplyAudioPreferences();combatReviewFreeze=false;ReturnHome();
   File.WriteAllText(Path.Combine(folder,"PASS.txt"),"PASS: three real display-mode requests; separate saved settings; master/category volume values; JSON remap roundtrip; conflict swapping; actual rebound Rage keys/buttons; input preferences and explicit controller selection; interactive capture; settings pause/return; Y resource focus, RB category, A dropdown, D-pad row and B return.\n");Debug.Log("VEILBOUND_GAME_SETTINGS_PASS");
  }
